(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const sx = x + w1x, sy = y + w1y;
  const w2x = Math.sin(sx*0.025+sy*0.01+t*0.4)*8;
  const w2y = Math.cos(sx*0.01-sy*0.025-t*0.3)*8;
  const wx = sx + w2x, wy = sy + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.05],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [200+Math.sin(t*0.45+3)*110, 40+Math.cos(t*0.65+1)*80, 0.14, 3.1, 0.6],
    [350+Math.cos(t*0.55+2)*90, 200+Math.sin(t*0.45+4)*70, 0.11, 2.8, 0.65]
  ];
  let aS = 0, iS = 0, harm = 0;
  for (const [sX, sY, f, sp, w] of src) {
    const d = Math.sqrt((wx-sX)**2 + (wy-sY)**2);
    aS += Math.sin(d*f - t*sp) * w;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * w;
    harm += Math.sin(d*f*1.5 - t*sp*1.3 + 0.7) * w * 0.3;
  }
  const act = aS/8, inh = iS/8;
  const bg1 = (Math.sin(wx*0.04+wy*0.025+t*0.8) + Math.sin(wx*0.03-wy*0.04+t*1.1))/2;
  const bg2 = Math.sin((wx+wy)*0.12+t*2.5)*0.2 + Math.sin((wx-wy)*0.1-t*2)*0.2;
  const bg3 = Math.sin(wx*0.08+wy*0.06-t*0.5)*0.15 + Math.sin(wx*0.06-wy*0.09+t*0.7)*0.15;
  const bg = bg1 + bg2 + bg3;
  const dist = Math.sqrt((wx-cx)**2 + (wy-cy)**2);
  const ang = Math.atan2(wy-cx, wx-cx);
  const sp1 = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const sp2 = Math.sin(dist*0.07-ang*5+t*0.9)*0.2 + Math.sin(dist*0.03+ang*2-t*2.1)*0.15;
  const frac = Math.sin(wx*0.15+Math.sin(wy*0.12+t*0.5)*2)*Math.sin(wy*0.13+Math.sin(wx*0.11-t*0.4)*2)*0.3;
  const reaction = Math.tanh((act - inh*0.7 + bg*0.3 + sp1 + sp2 + harm*0.4 + frac)*2.0);
  const cell = Math.tanh((Math.sin(wx*0.15)*Math.sin(wy*0.15) + Math.sin((wx+wy)*0.1+t)*0.5)*1.5)*0.3;
  const dx = Math.sin((wx+1)*0.15)*Math.sin(wy*0.15) - Math.sin((wx-1)*0.15)*Math.sin(wy*0.15);
  const dy = Math.sin(wx*0.15)*Math.sin((wy+1)*0.15) - Math.sin(wx*0.15)*Math.sin((wy-1)*0.15);
  const edge = Math.sqrt(dx*dx + dy*dy);
  const blend = reaction*0.65 + cell*0.2 + edge*0.15;
  const v = blend*0.5+0.5;
  const pal = [
    [6,12,52],[12,45,85],[18,85,120],[25,140,135],[60,175,130],
    [180,195,75],[220,175,55],[215,120,65],[195,75,65],[155,45,75],
    [90,25,65],[35,15,55],[6,12,52]
  ];
  const idx = v*(pal.length-1);
  const i = Math.min(idx|0, pal.length-2);
  const f = idx-i;
  const lum = 0.75 + Math.sin(reaction*Math.PI)*0.15 + Math.abs(edge)*0.1;
  const glow = Math.max(0, -reaction*0.3);
  const hi = Math.abs(reaction)>0.75 ? 1.12 : 1.0;
  const vig = 1.0 - Math.sqrt((x-cx)**2+(y-cy)**2)/400*0.15;
  const pulse = 0.95 + Math.sin(t*0.8)*0.05;
  const m = lum*hi*vig*pulse;
  return [
    Math.min(255, Math.max(0, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*m + glow*30))|0,
    Math.min(255, Math.max(0, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*m + glow*25))|0,
    Math.min(255, Math.max(0, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*m + glow*40))|0
  ];
}
